});
backgroundThread.start();"},{"order":8,"type":"heading","text":"Introduction to ExecutorService"},{"order":9,"type":"paragraph","text":"Creating a new Thread for every background task is expensive. Thread creation involves overhead in terms of CPU time and memory. ExecutorService is part of the java.util.concurrent package and provides a managed pool of threads, abstracting away thread creation and management."},{"order":10,"type":"subheading","text":"Common Types of Executors"},{"order":11,"type":"bullet_point","text":"NewFixedThreadPool: Reuses a fixed number of threads operating off a shared unbounded queue."},{"order":12,"type":"bullet_point","text":"NewCachedThreadPool: Creates new threads as needed, but will reuse previously constructed threads when they are available."},{"order":13,"type":"bullet_point","text":"NewSingleThreadExecutor: Uses a single worker thread operating off an unbounded queue, ensuring tasks are executed sequentially."},{"order":14,"type":"heading","text":"Implementing ExecutorService in Android"},{"order":15,"type":"paragraph","text":"Here is a practical example of how to use ExecutorService to run a background task and post the result back to the Android Main (UI) thread using a Handler."},{"order":16,"type":"code","text":"import android.os.Handler;
import android.os.Looper;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class TaskRunner {
    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final Handler handler = new Handler(Looper.getMainLooper());

    public interface Callback<T> {
        void onComplete(T result);
    }

    public <T> void executeAsync(Callable<T> callable, Callback<T> callback) {
        executor.execute(new Runnable() {
            @Override
            public void run() {
                try {
                    final T result = callable.call();
                    handler.post(new Runnable() {
                        @Override
                        public void run() {
                            callback.onComplete(result);
                        }
                    });
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        });
    }

    public interface Callable<T> {
        T call() throws Exception;
    }
}"},{"order":17,"type":"heading","text":"Best Practices for Android Concurrency"},{"order":18,"type":"bullet_point","text":"Always shutdown your ExecutorService when your Activity or Fragment is destroyed to prevent memory leaks and wasted resources."},{"order":19,"type":"bullet_point","text":"Never update UI elements directly from a background thread; always use a Handler attached to Looper.getMainLooper()."},{"order":20,"type":"bullet_point","text":"For modern Android development, consider using Kotlin Coroutines as a higher-level abstraction over these threading concepts."}]
